def barcha_to_unlimited(apps, schema_editor):
    """Avval "Barcha to'plamlar" kabi elementlar limit=0 bilan saqlangan, 0 esa "ruxsat yo'q" deb o'qilardi."""
    Item = apps.get_model("services", "PackageServiceItem")
    for item in Item.objects.filter(limit=0):
        name = re.sub(r"<[^>]+>|&nbsp;", " ", item.name_uz or "").strip().lower()
        if name.startswith("barcha"):
            item.limit = -1
            item.save(update_fields=["limit"])


